begin;
select plan(28);
select has_table('public','marketplace_bundles','bundles are durable');
select has_table('public','marketplace_bundle_items','bundle version pins are durable');
select has_table('public','marketplace_private_spaces','private tenant marketplace exists');
select has_table('public','marketplace_private_space_members','private marketplace membership is explicit');
select has_table('public','marketplace_private_listings','private listing grants are durable');
select has_table('public','marketplace_licenses','workspace licenses are durable');
select has_table('public','marketplace_promotions','promotion lifecycle is durable');
select has_table('public','marketplace_discovery_events','privacy-minimized discovery analytics exists');
select ok((select relrowsecurity from pg_class where oid='public.marketplace_bundles'::regclass),'bundle RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.marketplace_private_spaces'::regclass),'private spaces RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.marketplace_private_space_members'::regclass),'private membership RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.marketplace_private_listings'::regclass),'private listing RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.marketplace_licenses'::regclass),'license RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.marketplace_promotions'::regclass),'promotion RLS enabled');
select ok(not has_table_privilege('anon','public.marketplace_private_spaces','SELECT'),'anonymous cannot read private marketplace');
select ok(not has_table_privilege('authenticated','public.marketplace_private_listings','SELECT'),'direct authenticated private listing access is denied');
select ok(not has_table_privilege('authenticated','public.marketplace_licenses','SELECT'),'direct authenticated license access is denied');
select ok(not has_table_privilege('authenticated','public.marketplace_promotions','SELECT'),'promotion billing and approval records are private');
select has_function('public','marketplace_assign_license_seat','license seat assignment is server controlled');
select ok(not has_function_privilege('anon','public.marketplace_assign_license_seat(uuid,uuid,uuid,uuid)','EXECUTE'),'anonymous cannot assign license seats');
select ok(not has_function_privilege('authenticated','public.marketplace_assign_license_seat(uuid,uuid,uuid,uuid)','EXECUTE'),'authenticated users cannot bypass workspace seat manager');
select has_function('public','marketplace_record_promotion_charge','promotion purchase is budget gated');
select has_function('public','marketplace_record_promotion_spend','promotion spend is recorded atomically');
select has_function('public','marketplace_refund_promotion','promotion refund is restricted to service role');
select ok(not has_function_privilege('authenticated','public.marketplace_refund_promotion(uuid,text,bigint,uuid,text)','EXECUTE'),'authenticated users cannot issue promotion refunds');
select has_table('public','marketplace_api_key_audit','developer API key audit is durable');
select ok((select relrowsecurity from pg_class where oid='public.marketplace_api_key_audit'::regclass),'developer API audit RLS enabled');
select ok(not has_table_privilege('authenticated','public.marketplace_api_key_audit','SELECT'),'developers cannot read cross-key audit records');
select * from finish();
rollback;
